// Gỡ đính kèm file con khỏi file cha (xóa parent_id trong DB)
const handleDetach = async (childFile) => {
  if (!confirm(`Xác nhận gỡ đính kèm file "${childFile.name || childFile.file_name}" khỏi văn bản cha?`)) return;
  try {
    await fetch('/api/drive/attach', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'detach', child_id: childFile.id }),
    });
    // Cập nhật local state: xóa parent_id của file con
    setFolderFiles(prev => prev.map(f => f.id === childFile.id ? { ...f, parent_id: null } : f));
  } catch (err) {
    alert('Lỗi khi gỡ đính kèm: ' + err.message);
  }
};

// Gỡ Phiếu trình khỏi Công văn đi
const handleDetachPhieuTrinh = async (phieuTrinhId, cvId) => {
  if (!confirm('Xác nhận gỡ Phiếu trình khỏi Công văn đi này?')) return;
  try {
    const res = await fetch('/api/drive/attach', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'detach-phieu-trinh', child_id: phieuTrinhId }),
    });
    const json = await res.json();
    if (json.success) {
      // Xóa phieu_trinh khỏi Công văn đi trong state, đưa Phiếu trình về lại danh sách
      setFolderFiles(prev => prev.map(f => {
        if (f.id === cvId) return { ...f, phieu_trinh: null };
        return f;
      }));
    } else {
      alert('Lỗi: ' + json.error);
    }
  } catch (err) {
    alert('Lỗi khi gỡ Phiếu trình: ' + err.message);
  }
};

// Xác nhận gắn Phiếu trình vào Công văn đi
const handleConfirmAttachPhieuTrinh = async () => {
  if (!attachPhieuTrinhTargetId || !attachingPhieuTrinh) return;
  setIsAttachingPhieuTrinh(true);
  try {
    const res = await fetch('/api/drive/attach', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'attach-phieu-trinh',
        child_id: attachPhieuTrinhTargetId,   // ID file Phiếu trình
        parent_id: attachingPhieuTrinh.id,      // ID Công văn đi
      }),
    });
    const json = await res.json();
    if (json.success) {
      // Cập nhật state: gắn phieu_trinh vào CV đi, ẩn file PT khỏi danh sách
      const ptObj = json.phieu_trinh;
      setFolderFiles(prev => {
        // Gắn PT vào Công văn đi
        let updated = prev.map(f => {
          if (f.id === attachingPhieuTrinh.id) return { ...f, phieu_trinh: ptObj };
          return f;
        });
        // Ẩn file Phiếu trình khỏi danh sách chính
        updated = updated.filter(f => f.id !== attachPhieuTrinhTargetId);
        return updated;
      });
      setAttachingPhieuTrinh(null);
      setAttachPhieuTrinhTargetId('');
      setAttachPhieuTrinhSearch('');
    } else {
      alert('Lỗi gắn Phiếu trình: ' + json.error);
    }
  } catch (err) {
    alert('Lỗi kết nối: ' + err.message);
  } finally {
    setIsAttachingPhieuTrinh(false);
  }
};

